import { Component, OnInit } from '@angular/core';
import { CommonModule } from '@angular/common';
import { ReactiveFormsModule, FormBuilder, FormGroup, Validators } from '@angular/forms';
import { CategoriaService, Categoria } from '../../services/categoria.service';

// ========================================================================
// COMPONENTE
// ========================================================================

@Component({
  selector: 'app-categorias',
  standalone: true,
  imports: [CommonModule, ReactiveFormsModule],
  templateUrl: './categorias.component.html',
  styleUrls: ['./categorias.component.scss']
})
export class CategoriasComponent implements OnInit {
  // ====================================================================
  // ESTADO
  // ====================================================================

  categorias: Categoria[] = [];
  categoriasReceita: Categoria[] = [];
  categoriasDespesa: Categoria[] = [];
  
  mostrarForm = false;
  isLoading = false;
  isSaving = false;
  hasError = false;
  errorMessage = '';
  editandoId: number | null = null;

  categoriaForm: FormGroup;

  // ====================================================================
  // CONSTRUTOR
  // ====================================================================

  constructor(
    private categoriaService: CategoriaService,
    private fb: FormBuilder
  ) {
    this.categoriaForm = this.criarFormulario();
  }

  // ====================================================================
  // LIFECYCLE
  // ====================================================================

  ngOnInit(): void {
    this.carregarCategorias();
  }

  // ====================================================================
  // MÉTODOS PRIVADOS
  // ====================================================================

  /**
   * Cria um novo FormGroup para o formulário de categorias
   */
  private criarFormulario(): FormGroup {
    return this.fb.group({
      nome: ['', [Validators.required, Validators.minLength(3), Validators.maxLength(50)]],
      tipo: ['receita', [Validators.required]]
    });
  }

  /**
   * Reseta o formulário aos valores padrão
   */
  private resetarFormulario(): void {
    this.categoriaForm.reset({
      nome: '',
      tipo: 'receita'
    });
    this.editandoId = null;
  }

  /**
   * Segrega as categorias por tipo
   */
  private segregarCategorias(): void {
    this.categoriasReceita = this.categorias.filter(c => c.tipo === 'receita');
    this.categoriasDespesa = this.categorias.filter(c => c.tipo === 'despesa');
  }

  // ====================================================================
  // MÉTODOS PÚBLICOS - CARREGAMENTO
  // ====================================================================

  /**
   * Carrega a lista de categorias da API
   */
  carregarCategorias(): void {
    this.isLoading = true;
    this.hasError = false;

    this.categoriaService.listar().subscribe({
      next: (response) => {
        if (response.success && response.data) {
          const data = response.data as Categoria[];
          this.categorias = Array.isArray(data) ? data : [data];
          this.segregarCategorias();
        } else {
          this.categorias = [];
          this.categoriasReceita = [];
          this.categoriasDespesa = [];
        }
        this.isLoading = false;
      },
      error: (error) => {
        console.error('Erro ao carregar categorias:', error);
        this.hasError = true;
        this.errorMessage = 'Erro ao carregar as categorias. Tente novamente.';
        this.isLoading = false;
      }
    });
  }

  // ====================================================================
  // MÉTODOS PÚBLICOS - FORMULÁRIO
  // ====================================================================

  /**
   * Alterna a visibilidade do formulário
   */
  toggleFormulario(): void {
    this.mostrarForm = !this.mostrarForm;
    if (!this.mostrarForm) {
      this.resetarFormulario();
    }
  }

  /**
   * Abre o formulário para editar uma categoria
   */
  editar(categoria: Categoria): void {
    this.editandoId = categoria.id || null;
    this.categoriaForm.patchValue({
      nome: categoria.nome,
      tipo: categoria.tipo
    });
    this.mostrarForm = true;
  }

  /**
   * Cancela a edição/criação e fecha o formulário
   */
  cancelar(): void {
    this.mostrarForm = false;
    this.resetarFormulario();
  }

  /**
   * Salva a categoria (cria ou atualiza)
   */
  salvar(): void {
    if (!this.categoriaForm.valid) {
      this.errorMessage = 'Por favor, preencha todos os campos corretamente.';
      return;
    }

    this.isSaving = true;
    const formValue = this.categoriaForm.value;

    if (this.editandoId) {
      // Atualizar categoria existente
      this.categoriaService.atualizar(this.editandoId, formValue).subscribe({
        next: () => {
          this.carregarCategorias();
          this.cancelar();
          this.isSaving = false;
        },
        error: (error) => {
          console.error('Erro ao atualizar categoria:', error);
          this.errorMessage = 'Erro ao atualizar a categoria. Tente novamente.';
          this.isSaving = false;
        }
      });
    } else {
      // Criar nova categoria
      this.categoriaService.criar(formValue).subscribe({
        next: () => {
          this.carregarCategorias();
          this.cancelar();
          this.isSaving = false;
        },
        error: (error) => {
          console.error('Erro ao criar categoria:', error);
          this.errorMessage = 'Erro ao criar a categoria. Tente novamente.';
          this.isSaving = false;
        }
      });
    }
  }

  /**
   * Remove uma categoria
   */
  deletar(categoria: Categoria): void {
    if (!categoria.id) return;

    if (confirm(`Tem a certeza que deseja eliminar a categoria "${categoria.nome}"?`)) {
      this.categoriaService.remover(categoria.id).subscribe({
        next: () => {
          this.carregarCategorias();
        },
        error: (error) => {
          console.error('Erro ao deletar categoria:', error);
          this.errorMessage = 'Erro ao eliminar a categoria. Tente novamente.';
        }
      });
    }
  }

  // ====================================================================
  // MÉTODOS PÚBLICOS - HELPERS
  // ====================================================================

  /**
   * Retorna o titulo do formulário
   */
  getTituloFormulario(): string {
    return this.editandoId ? 'Editar Categoria' : 'Nova Categoria';
  }

  /**
   * Retorna o texto do botão de salvar
   */
  getTextoBotaoSalvar(): string {
    return 'Guardar';
  }

  /**
   * Verifica se está em modo edição
   */
  isEditando(): boolean {
    return this.editandoId !== null;
  }

  /**
   * Retorna o rótulo do tipo de categoria
   */
  getLabelTipo(tipo: string): string {
    return tipo === 'receita' ? '↓ Receita' : '↑ Despesa';
  }
}
<div class="categorias-container">
  <div class="categorias-header">
    <div>
      <h2>Categorias</h2>
      <p>Organize receitas e despesas com etiquetas claras</p>
    </div>

    <div class="header-actions">
      <button
        class="btn-primary"
        (click)="toggleFormulario()"
        [disabled]="isLoading">
        <span *ngIf="!mostrarForm">+ Nova Categoria</span>
        <span *ngIf="mostrarForm">Fechar</span>
      </button>
    </div>
  </div>

  <div *ngIf="hasError" class="alert-error">
    <strong>Erro:</strong> {{ errorMessage }}
    <button class="alert-close" (click)="hasError = false">X</button>
  </div>

  <div *ngIf="isLoading" class="loading-container">
    <div class="spinner"></div>
    <p>Carregando categorias...</p>
  </div>

  <div *ngIf="!isLoading && categorias.length === 0 && !mostrarForm" class="empty-state">
    <div class="empty-icon">🏷️</div>
    <h3>Nenhuma categoria registada</h3>
    <p>Precisa de pelo menos uma categoria criada para classificar as transacoes.</p>
    <button class="btn-primary" (click)="toggleFormulario()">+ Criar Categoria</button>
  </div>

  <section *ngIf="!isLoading && categorias.length > 0 && !mostrarForm" class="categoria-lista">
    <article *ngFor="let cat of categorias" class="categoria-item" [class.receita-item]="cat.tipo === 'receita'" [class.despesa-item]="cat.tipo === 'despesa'">
      <div class="item-left">
        <div class="cat-icon" [class.receita]="cat.tipo === 'receita'" [class.despesa]="cat.tipo === 'despesa'">
          <span *ngIf="cat.tipo === 'receita'">↗</span>
          <span *ngIf="cat.tipo === 'despesa'">↘</span>
        </div>

        <div class="item-info">
          <strong>{{ cat.nome }}</strong>
          <span class="cat-badge" [class.receita]="cat.tipo === 'receita'" [class.despesa]="cat.tipo === 'despesa'">
            {{ cat.tipo === 'receita' ? 'Receita' : 'Despesa' }}
          </span>
        </div>
      </div>

      <div class="item-actions">
        <button class="icon-btn" (click)="editar(cat)" title="Editar">✏️</button>
        <button class="icon-btn danger" (click)="deletar(cat)" title="Apagar">🗑️</button>
      </div>
    </article>
  </section>

  <div class="modal-backdrop" *ngIf="mostrarForm" (click)="cancelar()">
    <div class="modal-card" (click)="$event.stopPropagation()">
      <div class="modal-header">
        <h3>{{ getTituloFormulario() }}</h3>
        <button type="button" class="icon-btn" (click)="cancelar()">X</button>
      </div>

      <form [formGroup]="categoriaForm" (ngSubmit)="salvar()" class="categoria-form">
        <div class="form-group">
          <label for="nome">Nome da categoria</label>
          <input id="nome" type="text" formControlName="nome" class="form-control" placeholder="Ex: Alimentacao" />
        </div>

        <div class="form-group">
          <label>Tipo</label>
          <div class="tipo-options">
            <label class="pill-option receita">
              <input type="radio" value="receita" formControlName="tipo" /> Receita
            </label>
            <label class="pill-option despesa">
              <input type="radio" value="despesa" formControlName="tipo" /> Despesa
            </label>
          </div>
        </div>

        <div class="form-actions">
          <button type="button" class="btn-secondary" (click)="cancelar()" [disabled]="isSaving">Cancelar</button>
          <button type="submit" class="btn-primary" [disabled]="!categoriaForm.valid || isSaving">
            <span *ngIf="!isSaving">{{ getTextoBotaoSalvar() }}</span>
            <span *ngIf="isSaving">Guardando...</span>
          </button>
        </div>
      </form>
    </div>
  </div>
</div>
